/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--ui-icon-size-md, 16px);
  height: var(--ui-icon-size-md, 16px);
  color: currentColor;
  vertical-align: middle;
  flex-shrink: 0;
}
:where([data-moru-registry]) .ui-spinner[data-size='sm'] {
  width: var(--ui-icon-size-sm, 14px);
  height: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-spinner[data-size='lg'] {
  width: var(--ui-icon-size-lg, 18px);
  height: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-spinner > svg {
  display: block;
  width: 100%;
  height: 100%;
  animation: moru-registry-ui-completion-spin 0.8s linear infinite;
}
:where([data-moru-registry]) .ui-spinner-segments {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12%;
  width: 100%;
  height: 100%;
}
:where([data-moru-registry]) .ui-spinner-segments > span {
  flex: 1 1 0;
  min-width: 0;
  background: currentColor;
  animation: moru-registry-ui-spinner-segment 1.2s ease-in-out infinite;
}
:where([data-moru-registry]) .ui-spinner[data-variant='dots'] .ui-spinner-segments > span {
  aspect-ratio: 1;
  border-radius: 50%;
}
:where([data-moru-registry]) .ui-spinner[data-variant='bars'] .ui-spinner-segments > span {
  height: 80%;
  border-radius: 999px;
  animation-name: moru-registry-ui-spinner-bar;
}
:where([data-moru-registry]) .ui-spinner-segments > span:nth-child(2) {
  animation-delay: 0.15s;
}
:where([data-moru-registry]) .ui-spinner-segments > span:nth-child(3) {
  animation-delay: 0.3s;
}
:where([data-moru-registry]) .ui-spinner[data-paused] > svg,
:where([data-moru-registry]) .ui-spinner[data-paused] .ui-spinner-segments > span {
  animation-play-state: paused;
}
@keyframes moru-registry-ui-spinner-segment {
  0%,
  80%,
  100% {
    opacity: 0.4;
    transform: scale(0.7);
  }
  40% {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes moru-registry-ui-spinner-bar {
  0%,
  80%,
  100% {
    opacity: 0.4;
    transform: scaleY(0.45);
  }
  40% {
    opacity: 1;
    transform: scaleY(1);
  }
}
@keyframes moru-registry-ui-completion-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-spinner > svg,
  :where([data-moru-registry]) .ui-spinner-segments > span {
    animation: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, type HTMLAttributes } from 'react'
import { cn } from './_lib/cn'
import './controls-shared.css'
import './spinner.css'

export type SpinnerProps = HTMLAttributes<HTMLSpanElement> & {
  size?: 'sm' | 'md' | 'lg'
  variant?: 'ring' | 'dots' | 'bars'
  label?: string
  paused?: boolean
  /** Use inside an already labelled loading button or status to avoid duplicate announcements. */
  decorative?: boolean
}
export const Spinner = forwardRef<HTMLSpanElement, SpinnerProps>(function Spinner(
  {
    size = 'md',
    variant = 'ring',
    label: labelProp,
    paused = false,
    decorative = false,
    className,
    ...props
  },
  ref,
) {
  const { t } = useI18n()
  const label = labelProp ?? t('불러오는 중')

  return (
    <span
      {...props}
      ref={ref}
      className={cn('ui-spinner', className)}
      data-size={size}
      data-variant={variant}
      data-paused={paused || undefined}
      role={decorative ? undefined : 'status'}
      aria-hidden={decorative ? true : props['aria-hidden']}
      aria-label={
        decorative || props['aria-labelledby'] ? undefined : (props['aria-label'] ?? label)
      }
      aria-labelledby={decorative ? undefined : props['aria-labelledby']}
      aria-live={decorative ? undefined : props['aria-live']}
    >
      {variant === 'ring' ? (
        <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
          <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".2" />
          <path
            d="M12 3a9 9 0 0 1 9 9"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
          />
        </svg>
      ) : (
        <span className="ui-spinner-segments" aria-hidden="true">
          <span />
          <span />
          <span />
        </span>
      )}
    </span>
  )
})
